#!/usr/bin/env node
/**
 * Publishes the shared map renderer to the C# site as ONE browser script.
 *
 *   pnpm --filter @shatteredarchive/shattered-maps-core build
 *   node scripts/publish-map-renderer.mjs [--out <folder>] [--check]
 *
 * The renderer (`renderSvg`) and the slicer (`sliceMap`) are the same code the Mapper runs. They live in shattered-maps-core, which is pure
 * ES modules with no dependencies, so the bundle is made by joining four compiled files (schema, hierarchy, terrainPalette, render) into one IIFE: no bundler,
 * no new dependency, byte-for-byte repeatable. The output is `worldmap2.js` plus `worldmap2.js.sha256` in the C# repo
 * (`Server/Server.Web.Public/wwwroot/js/maps`); the C# repo's `RendererBundleTests` compares the two, so a hand edit of the bundle fails.
 *
 * `--check` writes nothing and exits 1 when the files in the output folder differ from what this build would produce (use it after a core change).
 * The script refuses a module outside the closure it knows (an unexpected import means the bundle recipe needs a decision, not a guess).
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const DIST = path.join(here, '..', 'services', 'shattered-maps-core', 'dist');
const DEFAULT_OUT = 'C:/Projects/DSL/Server/Server.Web.Public/wwwroot/js/maps';
export const BUNDLE_NAME = 'worldmap2.js';
export const HASH_NAME = 'worldmap2.js.sha256';

/** The modules in dependency order, and what the page may call. Anything else a module imports is an error. */
export const MODULES = ['schema.js', 'hierarchy.js', 'terrainPalette.js', 'render.js'];
export const PUBLIC_NAMES = ['renderSvg', 'sliceMap', 'escapeXml', 'MAX_RENDER_ROOMS', 'DIRECTIONS', 'TERRAIN'];

/** Removes the module syntax from one compiled file; returns its code and the relative modules it imports. */
export function stripModule(name, source) {
  const imports = [];
  // tsc writes the platform's newline; the bundle must be the same bytes on every machine.
  let code = source.replace(/\r\n/g, '\n').replace(/^import[\s\S]*?from\s+'\.\/([^']+)';\r?\n/gm, (_m, target) => {
    imports.push(target);
    return '';
  });
  if (/^import\s/m.test(code)) throw new Error(`${name}: an import this script does not understand`);
  code = code.replace(/^\/\/# sourceMappingURL=.*$/gm, '');
  code = code.replace(/^export\s+(function|const|let|class)\s/gm, '$1 ');
  if (/^export\s/m.test(code)) throw new Error(`${name}: an export form this script does not understand`);
  return { code: code.trim(), imports };
}

/** The top-level names a stripped module declares. */
export function declaredNames(code) {
  const names = [];
  for (const m of code.matchAll(/^(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)/gm))
    names.push(m[1]);
  return names;
}

/** Joins the compiled files into the bundle text. `files` maps a file name to its compiled source. */
export function bundle(files) {
  const parts = [];
  const seen = new Map();
  for (const name of MODULES) {
    if (!(name in files)) throw new Error(`${name} is missing from the build`);
    const { code, imports } = stripModule(name, files[name]);
    for (const target of imports) {
      if (!MODULES.includes(target))
        throw new Error(`${name} imports ${target}, which is not part of the bundle recipe`);
      if (MODULES.indexOf(target) > MODULES.indexOf(name))
        throw new Error(`${name} imports ${target}, which would come after it`);
    }
    for (const declared of declaredNames(code)) {
      if (seen.has(declared)) throw new Error(`${name} declares ${declared}, which ${seen.get(declared)} declares too`);
      seen.set(declared, name);
    }
    parts.push(`// ---- ${name}\n${code}`);
  }
  for (const wanted of PUBLIC_NAMES) if (!seen.has(wanted)) throw new Error(`the bundle does not declare ${wanted}`);
  return [
    '// GENERATED by ShatteredArchive scripts/publish-map-renderer.mjs from shattered-maps-core (MIT, same author as the Mapper). Do not edit.',
    "// Exposes window.ShatteredMapsCore = { renderSvg, sliceMap, escapeXml, MAX_RENDER_ROOMS, DIRECTIONS, TERRAIN }. worldmap2.js.sha256 holds this file's hash.",
    '(function (global) {',
    "'use strict';",
    parts.join('\n\n'),
    `global.ShatteredMapsCore = Object.freeze({ ${PUBLIC_NAMES.join(', ')} });`,
    "})(typeof window !== 'undefined' ? window : globalThis);",
    '',
  ].join('\n');
}

export function hashFileText(text) {
  return `${crypto.createHash('sha256').update(text, 'utf8').digest('hex')}  ${BUNDLE_NAME}\n`;
}

function main(argv) {
  let out = DEFAULT_OUT;
  let check = false;
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--') continue;
    if (argv[i] === '--check') check = true;
    else if (argv[i] === '--out') out = argv[(i += 1)] ?? '';
    else throw new Error(`unknown argument: ${argv[i]}`);
  }
  if (!out) throw new Error('--out needs a folder');
  const files = {};
  for (const name of MODULES) {
    const file = path.join(DIST, name);
    if (!fs.existsSync(file))
      throw new Error(`${file} not found: run \`pnpm --filter @shatteredarchive/shattered-maps-core build\` first`);
    files[name] = fs.readFileSync(file, 'utf8');
  }
  const text = bundle(files);
  const hash = hashFileText(text);
  const bundlePath = path.join(out, BUNDLE_NAME);
  const hashPath = path.join(out, HASH_NAME);
  if (check) {
    const same =
      fs.existsSync(bundlePath) &&
      fs.existsSync(hashPath) &&
      fs.readFileSync(bundlePath, 'utf8') === text &&
      fs.readFileSync(hashPath, 'utf8') === hash;
    console.log(
      same ? `${BUNDLE_NAME} is up to date` : `${BUNDLE_NAME} differs from the build: run this script without --check`,
    );
    return same ? 0 : 1;
  }
  fs.mkdirSync(out, { recursive: true });
  fs.writeFileSync(bundlePath, text, 'utf8');
  fs.writeFileSync(hashPath, hash, 'utf8');
  console.log(`wrote ${bundlePath} (${text.length} characters) and ${HASH_NAME}: ${hash.trim()}`);
  return 0;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (error) {
    console.error(`publish-map-renderer: ${error instanceof Error ? error.message : error}`);
    process.exitCode = 1;
  }
}
